import React, { useCallback, useEffect, useMemo, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  Paper,
  Stack,
  Step,
  StepLabel,
  Stepper,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import ScrollableTableContainer from '../shared/ScrollableTableContainer';
import AdminPortalLayout from './AdminPortalLayout';
import AdminInternalNav from './AdminInternalNav';
import ApiService from '../../services/api';

type StepStatus = 'complete' | 'current' | 'upcoming';

interface ReviewStep {
  id: string;
  label: string;
  description: string;
  status: StepStatus;
}

interface ReviewItem {
  factorId: string;
  unit: string;
  category?: string | null;
  ghgScope?: string | null;
  currentFactor: number | null;
  proposedFactor: number;
  relativeUncertainty?: number | null;
  source?: string | null;
  sourceDocument?: string | null;
  sourceUrl?: string | null;
  changeReason?: string | null;
  reviewStatus: string;
  reviewNotes?: string | null;
}

interface ReviewRelease {
  releaseId: string;
  status: string;
  summary?: string | null;
  agentNotes?: string[];
  pendingCount: number;
  unchangedCount: number;
  approvedCount: number;
  rejectedCount: number;
}

interface ReviewWorkflow {
  cycle: string;
  steps: ReviewStep[];
  release: ReviewRelease | null;
  items: ReviewItem[];
  canPublish: boolean;
}

const currentCycle = () => new Date().toISOString().slice(0, 7);

const statusColor = (status: string): 'default' | 'success' | 'warning' | 'error' | 'info' => {
  if (status === 'approved' || status === 'published') return 'success';
  if (status === 'rejected') return 'error';
  if (status === 'pending_review' || status === 'in_review') return 'warning';
  return 'default';
};

const formatFactor = (value: number | null | undefined) => (
  value == null || Number.isNaN(Number(value)) ? '—' : String(value)
);

const parseUpdates = (raw: string) => {
  const trimmed = raw.trim();
  if (!trimmed) return [];
  const parsed = JSON.parse(trimmed);
  if (Array.isArray(parsed)) return parsed;
  if (parsed && Array.isArray(parsed.updates)) return parsed.updates;
  throw new Error('Paste a JSON array of factor updates, or an object with an updates array.');
};

const workflowFromResponse = (response: { data?: { workflow?: ReviewWorkflow } & ReviewWorkflow }) => (
  response?.data?.workflow || response?.data || null
);

const EmissionFactorReviewAdmin: React.FC = () => {
  const [cycle, setCycle] = useState(currentCycle);
  const [workflow, setWorkflow] = useState<ReviewWorkflow | null>(null);
  const [updatesText, setUpdatesText] = useState('');
  const [notes, setNotes] = useState('');
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [message, setMessage] = useState<string | null>(null);

  const loadWorkflow = useCallback(async (nextCycle = cycle) => {
    setLoading(true);
    setError(null);
    try {
      const response = await ApiService.getAdminEmissionFactorReview(nextCycle) as {
        data?: ReviewWorkflow;
      };
      setWorkflow(response?.data || null);
    } catch (err) {
      setWorkflow(null);
      setError(err instanceof Error ? err.message : 'Failed to load the factor review.');
    } finally {
      setLoading(false);
    }
  }, [cycle]);

  useEffect(() => {
    void loadWorkflow(cycle);
  }, [cycle, loadWorkflow]);

  const items = useMemo(() => workflow?.items || [], [workflow?.items]);
  const visibleItems = useMemo(() => {
    const query = search.trim().toLowerCase();
    if (!query) return items;
    return items.filter((item) => (
      item.factorId.toLowerCase().includes(query)
      || (item.source || '').toLowerCase().includes(query)
      || (item.changeReason || '').toLowerCase().includes(query)
    ));
  }, [items, search]);

  const pendingIds = items
    .filter((item) => item.reviewStatus === 'pending_review')
    .map((item) => item.factorId);
  const activeStepIndex = (workflow?.steps || []).findIndex((step) => step.status === 'current');
  const activeStep = activeStepIndex === -1 ? (workflow?.steps.length || 0) : activeStepIndex;
  const published = workflow?.release?.status === 'published';

  const runAction = async (action: () => Promise<unknown>, success: string) => {
    setBusy(true);
    setError(null);
    setMessage(null);
    try {
      const response = await action() as { data?: { workflow?: ReviewWorkflow } & ReviewWorkflow };
      const next = workflowFromResponse(response);
      if (next?.cycle) setWorkflow(next);
      else await loadWorkflow(cycle);
      setMessage(success);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'The review action failed.');
    } finally {
      setBusy(false);
    }
  };

  const openReview = () => {
    let updates: Array<Record<string, unknown>> = [];
    try {
      updates = parseUpdates(updatesText);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'The update JSON could not be read.');
      return;
    }
    void runAction(
      () => ApiService.proposeAdminEmissionFactorReview({ cycle, updates }),
      updates.length
        ? `Opened ${cycle} with ${updates.length} pasted update${updates.length === 1 ? '' : 's'}.`
        : `Opened ${cycle}. Factors that already match the catalog stay active.`
    );
  };

  const decide = (decision: 'approve' | 'reject', factorIds: string[]) => {
    void runAction(
      () => ApiService.reviewAdminEmissionFactors({
        cycle,
        decision,
        factorIds,
        notes: notes.trim() || undefined,
      }),
      decision === 'approve'
        ? `Approved ${factorIds.length} factor${factorIds.length === 1 ? '' : 's'}.`
        : `Rejected ${factorIds.length} factor${factorIds.length === 1 ? '' : 's'}.`
    );
  };

  return (
    <AdminPortalLayout
      title="Emission factor review"
      subtitle="Monthly internal review before calculation factors change."
    >
      <AdminInternalNav />
      <Stack spacing={2}>
        {error && <Alert severity="error" onClose={() => setError(null)}>{error}</Alert>}
        {message && <Alert severity="success" onClose={() => setMessage(null)}>{message}</Alert>}

        <Paper sx={{ p: 2 }}>
          <Stack direction={{ xs: 'column', md: 'row' }} spacing={2} alignItems={{ md: 'center' }}>
            <TextField
              label="Review cycle"
              value={cycle}
              onChange={(event) => setCycle(event.target.value)}
              placeholder="YYYY-MM"
              size="small"
              inputProps={{ 'aria-label': 'Review cycle' }}
            />
            <Button variant="outlined" onClick={() => { void loadWorkflow(cycle); }} disabled={loading || busy}>
              Refresh
            </Button>
            {workflow?.release && (
              <Chip
                label={workflow.release.status.replace('_', ' ')}
                color={statusColor(workflow.release.status)}
              />
            )}
          </Stack>
          <Stepper activeStep={activeStep} alternativeLabel sx={{ mt: 3 }}>
            {(workflow?.steps || []).map((step) => (
              <Step key={step.id} completed={step.status === 'complete'}>
                <StepLabel optional={<Typography variant="caption">{step.description}</Typography>}>
                  {step.label}
                </StepLabel>
              </Step>
            ))}
          </Stepper>
        </Paper>

        <Paper sx={{ p: 2 }}>
          <Typography variant="h6" gutterBottom>1. Open monthly review</Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Calculations keep using approved factors until you publish. Paste only sourced updates as JSON. Leave the box empty to queue factors that differ from the active registry.
          </Typography>
          <TextField
            label="Factor updates JSON"
            value={updatesText}
            onChange={(event) => setUpdatesText(event.target.value)}
            placeholder={'[{"factorId":"fuel_diesel","factor":2.68,"changeReason":"CEA table 1"}]'}
            multiline
            minRows={3}
            fullWidth
            disabled={published || busy}
          />
          <Box sx={{ mt: 2 }}>
            <Button variant="contained" onClick={openReview} disabled={published || busy || loading}>
              Open review
            </Button>
          </Box>
          {workflow?.release?.summary && (
            <Typography variant="body2" sx={{ mt: 2 }}>{workflow.release.summary}</Typography>
          )}
          {workflow?.release?.agentNotes?.length ? (
            <Stack spacing={0.5} sx={{ mt: 1 }}>
              {workflow.release.agentNotes.map((note) => (
                <Typography key={note} variant="caption" color="text.secondary">{note}</Typography>
              ))}
            </Stack>
          ) : null}
        </Paper>

        <Paper sx={{ p: 2 }}>
          <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1} justifyContent="space-between" sx={{ mb: 2 }}>
            <Typography variant="h6">2. Review proposed factors</Typography>
            <TextField
              size="small"
              label="Search factors"
              value={search}
              onChange={(event) => setSearch(event.target.value)}
            />
          </Stack>
          <TextField
            label="Review note"
            value={notes}
            onChange={(event) => setNotes(event.target.value)}
            fullWidth
            size="small"
            sx={{ mb: 2 }}
          />
          <Stack direction="row" spacing={1} sx={{ mb: 2 }}>
            <Button
              size="small"
              variant="outlined"
              disabled={busy || pendingIds.length === 0}
              onClick={() => decide('approve', pendingIds)}
            >
              Approve all pending
            </Button>
            <Button
              size="small"
              color="error"
              variant="outlined"
              disabled={busy || pendingIds.length === 0}
              onClick={() => decide('reject', pendingIds)}
            >
              Reject all pending
            </Button>
          </Stack>
          <ScrollableTableContainer>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Factor</TableCell>
                  <TableCell>Current</TableCell>
                  <TableCell>Proposed</TableCell>
                  <TableCell>Unit</TableCell>
                  <TableCell>Uncertainty</TableCell>
                  <TableCell>Source</TableCell>
                  <TableCell>Reason</TableCell>
                  <TableCell>Status</TableCell>
                  <TableCell>Decision</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {visibleItems.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={9}>
                      {loading ? 'Loading review…' : 'No proposed changes for this cycle.'}
                    </TableCell>
                  </TableRow>
                )}
                {visibleItems.map((item) => (
                  <TableRow key={item.factorId}>
                    <TableCell>
                      <Typography variant="body2">{item.factorId}</Typography>
                      <Typography variant="caption" color="text.secondary">
                        {[item.ghgScope, item.category].filter(Boolean).join(' · ')}
                      </Typography>
                    </TableCell>
                    <TableCell>{formatFactor(item.currentFactor)}</TableCell>
                    <TableCell>{formatFactor(item.proposedFactor)}</TableCell>
                    <TableCell>{item.unit}</TableCell>
                    <TableCell>{formatFactor(item.relativeUncertainty)}</TableCell>
                    <TableCell>
                      {item.sourceUrl ? (
                        <a href={item.sourceUrl} target="_blank" rel="noreferrer">{item.source || item.sourceDocument}</a>
                      ) : (item.source || item.sourceDocument || '—')}
                    </TableCell>
                    <TableCell>{item.changeReason || '—'}</TableCell>
                    <TableCell>
                      <Chip size="small" label={item.reviewStatus.replace('_', ' ')} color={statusColor(item.reviewStatus)} />
                    </TableCell>
                    <TableCell>
                      <Stack direction="row" spacing={1}>
                        <Button
                          size="small"
                          disabled={busy || item.reviewStatus !== 'pending_review'}
                          onClick={() => decide('approve', [item.factorId])}
                        >
                          Approve
                        </Button>
                        <Button
                          size="small"
                          color="error"
                          disabled={busy || item.reviewStatus !== 'pending_review'}
                          onClick={() => decide('reject', [item.factorId])}
                        >
                          Reject
                        </Button>
                      </Stack>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </ScrollableTableContainer>
          {workflow?.release && (
            <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 1 }}>
              {workflow.release.unchangedCount} unchanged · {workflow.release.pendingCount} pending · {workflow.release.approvedCount} approved · {workflow.release.rejectedCount} rejected
            </Typography>
          )}
        </Paper>

        <Paper sx={{ p: 2 }}>
          <Typography variant="h6" gutterBottom>3. Publish approved factors</Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Publish activates approved rows and closes the previous version. Rejected rows stay out of calculations.
          </Typography>
          <Button
            variant="contained"
            disabled={busy || !workflow?.canPublish}
            onClick={() => {
              void runAction(
                () => ApiService.publishAdminEmissionFactorReview(cycle),
                `Published approved factors for ${cycle}.`
              );
            }}
          >
            Publish approved factors
          </Button>
        </Paper>
      </Stack>
    </AdminPortalLayout>
  );
};

export default EmissionFactorReviewAdmin;
